        "quote": "现在最重要的是把住院和手术安排往前推进，不是我们自己先下最后结论。"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00010",
        "explanation": "The doctor correctly uses the workspace to ground advice, separating confirmed findings from uncertainties.",
        "quote": "先给你们一个实用清单："
      }
    ],
